function leerVault() {
  // El texto lo resuelve el nodo "Extraer el texto", pero ese nodo se queda
  // SOLO con la clave que le pides y tira el resto del json, el nombre del
  // fichero incluido. Hay que ir a buscarlo al nodo de lectura, que saca los
  // items en el mismo orden, y emparejarlos por posicion.
  const leidos = $('Leer el vault').all();
  const ficheros = [];
  $input.all().forEach((item, i) => {
    const j = item.json ?? {};
    if (typeof j.contenido !== 'string' || !j.contenido) return;
    const src = leidos[i] ?? {};
    const nombre = src.json?.fileName ?? src.binary?.data?.fileName;
    // Sin nombre no se puede ni marcar el fichero ni citarlo: mejor saltarlo
    // que escribir en un sitio inventado.
    if (!nombre) return;
    ficheros.push({ nombre, texto: j.contenido });
  });
  return ficheros;
}

function frontmatter(texto) {
  // Un parser de YAML de tres lineas. Solo hay que leer lo que escribe
  // "Componer nota", que son pares clave: valor planos.
  const m = texto.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return {};
  const campos = {};
  for (const linea of m[1].split(/\r?\n/)) {
    const i = linea.indexOf(':');
    if (i === -1) continue;
    const clave = linea.slice(0, i).trim();
    let valor = linea.slice(i + 1).trim();
    if (valor.startsWith('"') && valor.endsWith('"')) {
      valor = valor.slice(1, -1).replace(/\\"/g, '"');
    }
    campos[clave] = valor;
  }
  return campos;
}

// Modo: Run Once for All Items.
// Saca un item por cada evento del vault que hay que llevar a Google Calendar:
// los que tienen fecha, no estan cancelados, no se han migrado ya y todavia no
// han pasado. Los pasados se quedan en el vault: ahi no molestan y en Google
// no aportan nada.
//
// Se puede ejecutar mas de una vez: lo que ya lleva "migrado" se salta.

const DURACION_H = 1;
const ahora = DateTime.now().setZone('Europe/Madrid');
const fmt = "yyyy-LL-dd'T'HH:mm:ss";

function cuerpoLimpio(texto, titulo) {
  // Lo que va en la descripcion: el texto de la nota sin frontmatter ni
  // titulo, y la transcripcion cruda sin las marcas de markdown.
  return texto
    .replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n?/, '')
    .replace(new RegExp('^# ' + titulo.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*$', 'm'), '')
    .replace(/<!-- transcripción cruda -->/, 'Transcripción original:')
    .replace(/^> ?/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const salida = [];

for (const f of leerVault()) {
  const fm = frontmatter(f.texto);
  if (String(fm.cancelado).trim() === 'true') continue;
  if (fm.migrado) continue;
  if (!fm.cuando) continue;
  const d = DateTime.fromISO(fm.cuando, { zone: 'Europe/Madrid' });
  if (!d.isValid || d < ahora) continue;

  const titulo = fm.titulo || f.nombre.replace(/\.md$/, '');
  const creado = DateTime.fromISO(String(fm.creado ?? ''), { zone: 'Europe/Madrid' });
  const pie = 'Apuntado por Alfred' +
    (creado.isValid ? ' el ' + creado.toFormat('dd/LL/yyyy HH:mm') : '') +
    '. Pasado del vault (' + f.nombre + ').';

  salida.push({
    json: {
      fichero: f.nombre,
      texto: f.texto,
      titulo,
      inicio: d.toFormat(fmt),
      fin: d.plus({ hours: DURACION_H }).toFormat(fmt),
      descripcion: [cuerpoLimpio(f.texto, titulo), '', pie].join('\n').trim(),
    },
  });
}

return salida;

// Modo: Run Once for All Items.
// Marca en el vault los eventos que Google ha aceptado. El que falle no se
// marca, y la proxima ejecucion lo vuelve a intentar.
//
// La nota no se borra: se queda como recuerdo de lo que dictaste, con el id
// del evento para poder encontrarlo. Lo que ya no hace es avisar, ni salir en
// la agenda, ni proponerse al cancelar: todo eso mira ahora en Google.

const pedidos = $('Eventos por migrar').all();
const salida = [];

$input.all().forEach((item, i) => {
  // El nodo HTTP pisa el json con la respuesta de Google: la nota hay que ir a
  // buscarla al item que lo origino.
  const id = item.json?.id;
  const p = pedidos[item.pairedItem?.item ?? i]?.json;
  if (!id || !p) return;
  const contenido = p.texto.replace(/^---\r?\n([\s\S]*?)\r?\n---/,
    (m, cuerpo) => '---\n' + cuerpo + '\nmigrado: gcal\ngcal_id: ' + id + '\n---');
  salida.push({ json: { fichero: p.fichero, titulo: p.titulo, contenido } });
});

return salida;
